export const sharedSkillRuleTrust: unknown = [{"skillId":"ath-case-design","version":"0.1.11","ruleVersion":"0.1.11","releaseDigest":"2dcc9e67f6aef08de24ca594e60ab9f140fbef55b4241960018e4920deaa796b","sourceArchives":[{"kind":"zip","fileName":"ath-case-design-0.1.11.zip","sha256":"a30bd4768e49794e459688a887e33b7055f85a527d9bb7e64434c3d74bd00d9c","bytes":18470},{"kind":"tgz","fileName":"aitesthub-case-design-skill-0.1.11.tgz","sha256":"fa428955e2caa48f958652ac589580fb5f425e39b708967f6c9170a420f95077","bytes":63733}],"manifestSha256":"314b703f3c94299e555beddc281d7bca934592f7fa2f3e05e35751f232df8701"},{"skillId":"ath-project-knowledge","version":"0.1.1","ruleVersion":"0.1.1","releaseDigest":"3dab8709928b02ff4fd5243d35e2520e0073798b6548115b0b2c0845107258e4","sourceArchives":[{"kind":"zip","fileName":"ath-project-knowledge-0.1.1.zip","sha256":"784ae87f627419918582d8b31b1976910bfeb5fa6d93e94cc7ba235df1f6b895","bytes":899683}],"manifestSha256":"4fd1e1e21e846b5107bcdb898a6fb48bd111a3f6a34b21cd088bdbc4c89b2319"},{"skillId":"ath-api-regression","version":"0.1.7","ruleVersion":"0.1.7","releaseDigest":"e2a04332c8e95f9ad794bc7f23b157ef4329063e2bd685e5186d6cf3926bf9f2","sourceArchives":[{"kind":"zip","fileName":"ath-api-regression-0.1.7.zip","sha256":"a5ef80b285592590b93b7c1fd62b151c7e3f24168a12337b8cd031df758a5e59","bytes":33938}],"manifestSha256":"91dc830d21aae95e60c2a3a32774544f6c06182a47927d4ae3a586b5606451b4"}];
